final class ConnectedComponentsResult {

    private final List<List<Integer>> components;

    ConnectedComponentsResult(List<List<Integer>> components) {
        Objects.requireNonNull(components, "components");

        List<List<Integer>> snapshot = new ArrayList<>(components.size());
        for (List<Integer> component : components) {
            snapshot.add(List.copyOf(component));
        }

        this.components = List.copyOf(snapshot);
    }

    int componentCount() {
        return components.size();
    }

    List<List<Integer>> components() {
        return components;
    }

    String format() {
        return ComponentFormatter.format(components);
    }

    @Override
    public String toString() {
        return components.toString();
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Queue;

final class GraphComponentFinder {

    private GraphComponentFinder() {
    }

    static ConnectedComponentsResult findConnectedComponents(Graph graph) {
        Objects.requireNonNull(graph, "graph");

        int vertexCount = graph.vertexCount();
        validateVertexCount(vertexCount);
        boolean[] visited = new boolean[vertexCount];
        List<List<Integer>> components = new ArrayList<>();

        for (int vertex = 0; vertex < vertexCount; vertex++) {
            if (!visited[vertex]) {
                components.add(traverseComponent(graph, vertex, vertexCount, visited));
            }
        }

        return new ConnectedComponentsResult(components);
    }

    private static List<Integer> traverseComponent(
            Graph graph,
            int startVertex,
            int vertexCount,
            boolean[] visited) {
        Queue<Integer> pendingVertices = new ArrayDeque<>();
        List<Integer> component = new ArrayList<>();

        visited[startVertex] = true;
        pendingVertices.add(startVertex);

        while (!pendingVertices.isEmpty()) {
            int currentVertex = pendingVertices.remove();
            component.add(currentVertex);

            for (int neighbor : graph.neighborsOf(currentVertex)) {
                validateNeighborVertex(neighbor, vertexCount);
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    pendingVertices.add(neighbor);
                }
            }
        }

        return List.copyOf(component);
    }

    private static void validateVertexCount(int vertexCount) {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("Vertex count must be non-negative.");
        }
    }

    private static void validateNeighborVertex(int vertex, int vertexCount) {
        if (vertex < 0 || vertex >= vertexCount) {
            throw new IllegalArgumentException("Neighbor index out of bounds: " + vertex);
        }
    }
}

import java.util.List;

final class ComponentFormatter {

    private ComponentFormatter() {
    }

    static String format(List<List<Integer>> components) {
        StringBuilder output = new StringBuilder();

        for (int componentIndex = 0; componentIndex < components.size(); componentIndex++) {
            if (componentIndex > 0) {
                output.append(System.lineSeparator());
            }

            appendComponent(output, components.get(componentIndex));
        }

        return output.toString();
    }

    private static void appendComponent(StringBuilder output, List<Integer> component) {
        for (int vertexIndex = 0; vertexIndex < component.size(); vertexIndex++) {
            if (vertexIndex > 0) {
                output.append(' ');
            }

            output.append(component.get(vertexIndex));
        }
    }
}

